prelude:
class ListNode {
  val int
  next ListNode?
}

starter:
function ReverseList(head: ListNode?) -> ListNode? {
  // Reverse the singly linked list and return the new head.
  return head;
}

solution:
function ReverseHelper(cur: ListNode?, prev: ListNode?) -> ListNode? {
  if (cur == null) {
    return prev;
  }
  return ReverseHelper(cur.next, ListNode { val: cur.val, next: prev });
}

function ReverseList(head: ListNode?) -> ListNode? {
  return ReverseHelper(head, null);
}
